using Nebula.Patches;
using Virial;
using Virial.Components;
using Virial.Events.Game;
using Virial.Game;

namespace Nebula.Modules.ScriptComponents;

public static class HighlightHelpers
{
    public static void SetHighlight(Renderer renderer, UnityEngine.Color color)
    {
        renderer.material.SetFloat("_Outline", 1f);
        renderer.material.SetColor("_OutlineColor", color);
        HighlightManager.AddHighlightedRenderer(renderer);
    }

    internal static void SetHighlight(GamePlayer player, UnityEngine.Color color) => SetHighlight(player.VanillaPlayer.cosmetics.currentBodySprite.BodySprite, color);
    internal static void SetHighlight(DeadBody? player, UnityEngine.Color color)
    {
        if (player != null) SetHighlight(player.bodyRenderers[0], color);
    }

    public static void SetHighlight(GamePlayer player, Virial.Color color) => SetHighlight(player, color.ToUnityColor());
}

public static class ObjectTrackers
{
    static public Predicate<GamePlayer> StandardPredicateIgnoreOwner = p => p.CanBeTarget && !p.IsDead && !p.WillDie && !p.IsInvisible && !p.IsDived && !p.IsBlown;
    static public Predicate<GamePlayer> StandardPredicate = p => !p.AmOwner && StandardPredicateIgnoreOwner.Invoke(p);
    static public Predicate<GamePlayer> KillablePredicate(GamePlayer myPlayer) => p => StandardPredicate(p) && myPlayer.CanKill(p);
    static public Predicate<GamePlayer> LocalKillablePredicate = p => StandardPredicate(p) && (GamePlayer.LocalPlayer?.CanKill(p) ?? true);

    static public Predicate<IPlayerlike> PlayerlikeStandardPredicateIgnoreOwner = p => p.CanBeTarget && !p.IsDead && (p is not GamePlayer gp || (!gp.WillDie && !gp.IsInvisible && !gp.IsDived && !gp.IsBlown));
    static public Predicate<IPlayerlike> PlayerlikeStandardPredicate = p => !p.RealPlayer.AmOwner && PlayerlikeStandardPredicateIgnoreOwner.Invoke(p);
    static public Predicate<IPlayerlike> PlayerlikeKillablePredicate(GamePlayer myPlayer) => p => PlayerlikeStandardPredicate(p) && myPlayer.CanKill(p.RealPlayer);
    static public Predicate<IPlayerlike> PlayerlikeLocalKillablePredicate = p => PlayerlikeStandardPredicate(p) && (GamePlayer.LocalPlayer?.CanKill(p.RealPlayer) ?? true);

    public static ObjectTracker<GamePlayer> ForPlayer(ILifespan? lifespan, float? distance, GamePlayer tracker, Predicate<GamePlayer> predicate, UnityEngine.Color? color = null, bool canTrackInVent = false, bool ignoreCollider = false) => ForPlayer(lifespan, distance, tracker, predicate, null, color ?? UnityEngine.Color.yellow, canTrackInVent, ignoreCollider);
    public static ObjectTracker<GamePlayer> ForPlayer(ILifespan? lifespan, float? distance, GamePlayer tracker, Predicate<GamePlayer> predicate, Predicate<GamePlayer>? predicateHeavier, UnityEngine.Color? color, bool canTrackInVent = false, bool ignoreCollider = false)
    {
        if (!canTrackInVent)
        {
            var lastPredicate = predicate;
            predicate = p => !p.VanillaPlayer.inVent && lastPredicate(p);
        }
        IEnumerable<PlayerControl> FastPlayers() => PlayerControl.AllPlayerControls.GetFastEnumerator().Where(p => p);

        return new ObjectTrackerUnityImpl<GamePlayer, PlayerControl>(tracker.VanillaPlayer, distance ?? AmongUsLLImpl.Instance.VanillaKillDistance, FastPlayers, predicate, predicateHeavier, p => p.GetModInfo(), p => [p.GetTruePosition()], p => p.cosmetics.currentBodySprite.BodySprite, color, ignoreCollider).Register(lifespan);
    }

    public static ObjectTracker<IPlayerlike> ForPlayerlike(ILifespan? lifespan, float? distance, GamePlayer tracker, Predicate<IPlayerlike> predicate, UnityEngine.Color? color = null, bool canTrackInVent = false, bool ignoreCollider = false) => ForPlayerlike(lifespan, distance, tracker, predicate, null, color ?? UnityEngine.Color.yellow, canTrackInVent, ignoreCollider);
    public static ObjectTracker<IPlayerlike> ForPlayerlike(ILifespan? lifespan, float? distance, GamePlayer tracker, Predicate<IPlayerlike> predicate, Predicate<IPlayerlike>? predicateHeavier, UnityEngine.Color? color, bool canTrackInVent = false, bool ignoreCollider = false) => ForPlayerlike(lifespan, distance, () => tracker.TruePosition.ToUnityVector(), predicate, predicateHeavier, color, canTrackInVent, ignoreCollider);
    public static ObjectTracker<IPlayerlike> ForPlayerlike(ILifespan? lifespan, float? distance, Func<Vector2?> tracker, Predicate<IPlayerlike> predicate, Predicate<IPlayerlike>? predicateHeavier, UnityEngine.Color? color, bool canTrackInVent = false, bool ignoreCollider = false)
    {
        if (!canTrackInVent)
        {
            var lastPredicate = predicate;
            predicate = p => !p.Logic.InVent && lastPredicate(p);
        }

        return new ObjectTrackerUnityImpl<IPlayerlike, IPlayerlike>(tracker, distance ?? AmongUsLLImpl.Instance.VanillaKillDistance, () => NebulaGameManager.Instance!.AllPlayerlike, predicate, predicateHeavier, p => p, p => [p.TruePosition], p => p.VanillaCosmetics.currentBodySprite.BodySprite, color, ignoreCollider).Register(lifespan);
    }

    public static ObjectTracker<Virial.Game.DeadBody> ForDeadBody(ILifespan? lifespan, float? distance, GamePlayer tracker, Predicate<Virial.Game.DeadBody>? predicate = null, Predicate<Virial.Game.DeadBody>? predicateHeavier = null, UnityEngine.Color? color = null, bool ignoreCollider = false)
    {
        return new ObjectTrackerUnityImpl<Virial.Game.DeadBody, Virial.Game.DeadBody>(tracker.VanillaPlayer, distance ?? AmongUsLLImpl.Instance.VanillaKillDistance, () => ModSingleton<DeadBodyManager>.Instance.AllDeadBodies.Where(d => d.IsActive), predicate ?? (_ => true), predicateHeavier, d => d, d => [d.TruePosition], d => d.VanillaDeadBody.bodyRenderers[0], color, ignoreCollider).Register(lifespan);
    }

    public static ObjectTracker<Vent> ForVents(ILifespan? lifespan, float? distance, GamePlayer tracker, Predicate<Vent> predicate, UnityEngine.Color color, bool ignoreColliders = false)
    {
        return new ObjectTrackerUnityImpl<Vent, Vent>(tracker.VanillaPlayer, distance ?? AmongUsLLImpl.Instance.VanillaKillDistance, () => AmongUsLLImpl.ShipStatusInstance.AllVents, predicate, _ => true, v => v, v => [v.transform.GetPositionFast()], v => v.myRend, color, ignoreColliders).Register(lifespan);
    }
}



public class ObjectTrackerUnityImpl<V,T> : FlexibleLifespan, ObjectTracker<V>, IGameOperator where V : class
{
    V? ObjectTracker<V>.CurrentTarget => currentTarget?.Item2;
    bool ObjectTracker<V>.IsLocked { get => isLocked; set => isLocked = value; }
    bool ObjectTracker<V>.KeepAsLongAsPossible { get => isSoftLocked; set => isSoftLocked = value; }

    private Tuple<T,V>? currentTarget = null;

    Func<Vector2?> tracker;
    Func<IEnumerable<T>> allTargets;
    Predicate<V> predicate;
    Predicate<V>? predicateHeavier = null;
    Func<T, V> converter;
    Func<T, IEnumerable<UnityEngine.Vector2>> positionConverter;
    Action<T, bool, Color> highlightSetter;
    UnityEngine.Color color = UnityEngine.Color.yellow;
    bool ignoreColliders;
    bool ignoreShadows;
    float maxDistance;
    private bool isLocked = false;
    private bool isSoftLocked = false;
    public bool MoreHighlight = false;

    public ObjectTrackerUnityImpl(PlayerControl tracker, float maxDistance, Func<IEnumerable<T>> allTargets, Predicate<V> predicate, Predicate<V>? predicateHeavier, Func<T, V> converter, Func<T, IEnumerable<Vector2>> positionConverter, Func<T, SpriteRenderer> rendererConverter, Color? color = null, bool ignoreColliders = false, bool ignoreShadows = true)
    : this(() => tracker ? tracker.GetTruePosition() : null, maxDistance, allTargets, predicate, predicateHeavier, converter, positionConverter, rendererConverter, color, ignoreColliders, ignoreShadows) { }

    internal ObjectTrackerUnityImpl(Func<Vector2?> tracker, float maxDistance, Func<IEnumerable<T>> allTargets, Predicate<V> predicate, Predicate<V>? predicateHeavier, Func<T, V> converter, Func<T, IEnumerable<Vector2>> positionConverter, Func<T, SpriteRenderer> rendererConverter, Color? color = null, bool ignoreColliders = false, bool ignoreShadows = true)
        : this(tracker, maxDistance, allTargets, predicate, predicateHeavier, converter, positionConverter, (target, more, color) =>
        {
            var renderer = rendererConverter.Invoke(target);
            if (renderer)
            {
                if (more)
                    AmongUsUtil.SetHighlight(renderer, true, color);
                else
                    HighlightHelpers.SetHighlight(renderer, color);
            }
        }, color, ignoreColliders, ignoreShadows) { }

    private ObjectTrackerUnityImpl(Func<Vector2?> tracker, float maxDistance, Func<IEnumerable<T>> allTargets, Predicate<V> predicate, Predicate<V>? predicateHeavier, Func<T, V> converter, Func<T, IEnumerable<Vector2>> positionConverter, Action<T, bool, Color> highlightSetter, Color? color = null, bool ignoreColliders = false, bool ignoreShadows = true)
    {
        this.tracker = tracker;
        this.allTargets = allTargets;
        this.predicate = predicate;
        this.predicateHeavier = predicateHeavier;
        this.converter = converter;
        this.positionConverter = positionConverter;
        this.highlightSetter = highlightSetter;
        this.maxDistance = maxDistance;
        this.ignoreColliders = ignoreColliders;
        this.ignoreShadows = ignoreShadows;
        if (color.HasValue) this.color = color.Value;
        this.ignoreShadows = ignoreShadows;
    }

    public void SetColor(UnityEngine.Color color) => this.color = color;
    private void ShowTarget()
    {
        if (currentTarget == null) return;

        highlightSetter?.Invoke(currentTarget!.Item1, MoreHighlight, color);
    }

    void HudUpdate(GameHudUpdateEvent ev)
    {
        if (isLocked)
        {
            ShowTarget();
            return;
        }

        Vector2? calced = tracker.Invoke();
        if (!calced.HasValue)
        {
            currentTarget = null;
            return;

        }
        Vector2 myPos = calced.Value;

        float distance = maxDistance;
        Tuple<T,V>? candidate = null;

        foreach (var t in allTargets())
        {
            var v = converter(t);
            if (v == null) continue;

            if (!predicate(v)) continue;

            Vector2[] pos = positionConverter(t).ToArray();

            if (pos.Length == 0) continue;//点を持たないオブジェクトは無視する

            Vector2 dVec = pos[0] - myPos; //先頭を最たる中心として扱う
            float magnitude = dVec.magnitude;

            if (MoreHighlight && magnitude < 4.5f) highlightSetter?.Invoke(t, false, color);

            if (distance < magnitude) continue;

            if (!ignoreColliders && pos.All(p => PhysicsHelpers.AnyNonTriggersBetween(myPos, (p - myPos).normalized, magnitude, Constants.ShipAndObjectsMask))) continue;
            if (!ignoreShadows && pos.All(p => NebulaPhysicsHelpers.AnyShadowBetween(p, myPos, out _))) continue;
            if (!(predicateHeavier?.Invoke(v) ?? true)) continue;

            if (candidate != null && currentTarget != null && isSoftLocked && candidate.Item2 == currentTarget.Item2) continue;
            candidate = new(t,v);
            distance = magnitude;
        }

        currentTarget = candidate;
        ShowTarget();
    }
}

using AmongUs.Data;
using AmongUs.GameOptions;
using Nebula.Commands.Variations;
using Nebula.Modules.Logging;
using Virial;
using Virial.Command;
using Virial.Compat;
using Virial.Components;
using Virial.Events.Game;
using Virial.Events.Game.Meeting;
using Virial.Game;
using Virial.Media;
using Virial.Text;

namespace Nebula.Modules.ScriptComponents;

[NebulaPreprocess(PreprocessPhase.PostBuildNoS)]
public class ModAbilityButtonImpl : DependentLifespan, ModAbilityButton, IGameOperator
{
    private static readonly Image vanillaKillImage = SpriteLoader.FromResource("Nebula.Resources.Buttons.VanillaKillButton.png", 100f);
    internal static Image VanillaKillImage => vanillaKillImage;
    public class AbilityButtonStructure
    {
        public bool isLeftSide = false; 
        public bool showAlways = false;
        public bool arrangedAsKillButton = false;
        public int priority = 0;
        public IExecutable? onClick = null;
        public IExecutable? onSubClick = null;
        public TextComponent? label = null;
        public Image? image = null;
    }
    static ModAbilityButtonImpl()
    {
        EntityCommand.RegisterEntityDefinition("button", EntityCommand.GenerateDefinition(
            new Virial.Command.CommandStructureConverter<AbilityButtonStructure>()
            .Add<bool>("isLeftSide", (structure, val) => structure.isLeftSide = val)
            .Add<bool>("isRightSide", (structure, val) => structure.isLeftSide = !val)
            .Add<bool>("always", (structure, val) => structure.showAlways = val)
            .Add<bool>("asKillButton", (structure, val) => structure.arrangedAsKillButton = val)
            .Add<int>("priority", (structure, val) => structure.priority = Mathn.Clamp(val, 0, 9999))
            .Add<string>("rawLabel", (structure, val) => structure.label = new RawTextComponent(val))
            .Add<string>("localizedLabel", (structure, val) => structure.label = new TranslateTextComponent(val))
            .Add<IExecutable>("action", (structure, val) => structure.onClick = val)
            .Add<IExecutable>("aidAction", (structure, val) => structure.onSubClick = val)
            .Add<string>("icon", (structure, val) => structure.image = NebulaResourceManager.GetResource(val)?.AsImage(115f))
            , () => new AbilityButtonStructure(), val =>
            {
                var button = new ModAbilityButtonImpl(val.isLeftSide, val.arrangedAsKillButton, val.priority, val.showAlways);
                if(val.onClick != null) button.OnClick = b => NebulaManager.Instance.StartCoroutine(val.onClick!.CoExecute([]).CoWait().HighSpeedEnumerator().WrapToIl2Cpp());
                if(val.onSubClick != null) button.OnSubAction = b => NebulaManager.Instance.StartCoroutine(val.onSubClick!.CoExecute([]).CoWait().HighSpeedEnumerator().WrapToIl2Cpp());
                button.SetRawLabel(val.label?.GetString() ?? "button");
                if(val.image != null)button.SetSprite(val.image.GetSprite());
                return button;
            }));
    }

    public ActionButton VanillaButton { get; private set; }

    public IVisualTimer? CoolDownTimer { get; set; } = null;
    public IVisualTimer? EffectTimer { get; set; } = null;
    public IVisualTimer? CurrentTimer => (EffectActive && (EffectTimer?.IsProgressing ?? false)) ? EffectTimer : CoolDownTimer;
    public bool EffectActive = false;

    public static float CoolDownOnGameStart => GeneralConfigurations.ShortenCooldownAtGameStartOption;

    public Action<ModAbilityButtonImpl>? OnEffectStart { get; set; } = null;
    public Action<ModAbilityButtonImpl>? OnEffectEnd { get; set; } = null;
    public Action<ModAbilityButtonImpl>? OnUpdate { get; set; } = null;
    public Action<ModAbilityButtonImpl>? OnClick { get; set; } = null;
    public Action<ModAbilityButtonImpl>? OnSubAction { get; set; } = null;
    public Action<ModAbilityButtonImpl>? OnMeeting { get; set; } = null;
    public Action<ModAbilityButtonImpl>? OnStartTaskPhase { get; set; } = null;
    public Action<ModAbilityButtonImpl>? OnReleased { get; set; } = null;
    public Action<ModAbilityButtonImpl>? OnBroken { get; set; } = null;
    public Predicate<ModAbilityButtonImpl>? Availability { get; set; } = null;
    public Predicate<ModAbilityButtonImpl>? Visibility { get; set; } = null;
    private VirtualInput? keyCode { get; set; } = null;
    private VirtualInput? subKeyCode { get; set; } = null;
    private SpriteRenderer? brokenAlternative = null!;
    public bool IsBroken { get; set; } = false;
    public IUsurpableAbility? RelatedAbility { get; set; } = null;
    private HudContent gridContent;
    public ModAbilityButtonImpl(bool isLeftSideButton = false, bool isArrangedAsKillButton = false,int priority = 0, bool alwaysShow = false)
    {
        var vanillaKillButton = HudManager.Instance.KillButton;
        VanillaButton = UnityEngine.Object.Instantiate(vanillaKillButton, vanillaKillButton.transform.parent);
        VanillaButton.gameObject.ForEachChild((Il2CppSystem.Action<GameObject>)((c) => { if (c.name.Equals("HotKeyGuide")) GameObject.Destroy(c); }));
        var cooldownText = VanillaButton.cooldownTimerText;
        cooldownText.gameObject.SetActive(true);
        VanillaButton.buttonLabelText.transform.SetLocalZ(-0.001f);
        SetSprite(vanillaKillImage.GetSprite());

        VanillaButton.buttonLabelText.GetComponent<TextTranslatorTMP>().enabled = false;
        var passiveButton = VanillaButton.GetComponent<PassiveButton>();
        passiveButton.OnClick = new UnityEngine.UI.Button.ButtonClickedEvent();
        passiveButton.OnClick.AddListener(() => DoClick());

        gridContent = VanillaButton.gameObject.GetComponent<HudContent>();
        gridContent.UpdateSubPriority();
        gridContent.MarkAsKillButtonContent(isArrangedAsKillButton);
        gridContent.SetPriority(priority);
        gridContent.IsStaticContent = alwaysShow;
        NebulaGameManager.Instance?.HudGrid.RegisterContent(gridContent, isLeftSideButton);

        SetLabelType(ModAbilityButton.LabelType.Standard);

        NebulaManager.Instance.ScheduleDelayAction(PlayFlashOnce);

        cooldownTextColorObserver = new(false, inEffect => cooldownText.color = (inEffect ? VColor.Green : VColor.White).ToUnityColor(), true);
        cooldownTextObserver = new("", text => cooldownText.text = text, true);
    }

    int IHudContent.Priority { get => gridContent.Priority; set => gridContent.SetPriority(Mathn.Clamp(value, -5000, 9999)); }
    bool IHudContent.IsLeftSide => gridContent.IsLeftSide;
    bool IHudContent.IsKillButtonContent { get => gridContent.MarkedAsKillButtonContent; set => gridContent.MarkAsKillButtonContent(value); }
    bool IHudContent.IsStaticContent => gridContent.IsStaticContent;
    bool IHudContent.ShouldBeInLastLine { get => gridContent.ShouldBeInLastLine; set => gridContent.ShouldBeInLastLine = value; }

    void TryGenerateBrokenAlternative()
    {
        if (!brokenAlternative)
        {
            brokenAlternative = UnityHelper.CreateObject<SpriteRenderer>("Broken", VanillaButton.transform, UnityEngine.Vector3.zero);
            brokenAlternative.sprite = VanillaButton.graphic.sprite;
            brokenAlternative.material = NebulaAsset.BrokenShaderMat;
            brokenAlternative.gameObject.SetActive(false);
            NebulaAsset.PlaySE(NebulaAudioClip.ButtonBreaking,pitch: System.Random.Shared.NextSingle() * 0.2f + 0.7f,volume: 1f);
        }
    }
    void IGameOperator.OnReleased()
    {
        if (VanillaButton.AsBoolFast())
        {
            OnReleased?.Invoke(this);
            UnityEngine.Object.Destroy(VanillaButton.gameObject);
        }
    }

    private bool CheckMouseClick()
    {
        if (Input.GetKeyDown(KeyCode.Mouse0))
        {
            if (NebulaInput.SomeUiIsActive || AmongUsUtil.MapIsOpen) return false;

            var dis = (VVector2)Input.mousePosition - new VVector2(NebulaAPI.AmongUs.ScreenWidth, NebulaAPI.AmongUs.ScreenHeight) * 0.5f;
            return dis.Magnitude < 280f;
        }
        return false;
    }

    public bool IsVisible => Visibility?.Invoke(this) ?? true;
    public bool IsAvailable => IsVisible && IsAvailableUnsafe;
    private bool IsAvailableUnsafe => Availability?.Invoke(this) ?? true;

    public Func<ModAbilityButtonImpl, bool>? PlayFlashWhile { get; set; } = null;
    private float playFlashTimer = 0f;

    private IEnumerator CoFlash()
    {
        var renderer = UnityHelper.CreateObject<SpriteRenderer>("Flash", VanillaButton.transform, new(0f, 0f, -1f));
        renderer.sprite = VanillaButton.graphic.sprite;
        renderer.material = new(NebulaAsset.WhiteShader);
        renderer.material.SetColor("_Color", new(1f, 1f, 1f, 1f));
        yield return null;

        float a = 1f;
        while (a > 0f)
        {
            if (!renderer) yield break;
            renderer.transform.localScale = UnityEngine.Vector3.one * (2f - a);
            renderer.material.SetColor("_Color", new(1f, 1f, 1f, a * 0.85f));
            a -= Time.deltaTime * 1.5f;
            yield return null;
        }

        GameObject.Destroy(renderer.gameObject);
    }

    public void PlayFlashOnce()
    {
        NebulaManager.Instance.StartCoroutine(CoFlash().WrapToIl2Cpp());
    }

    void PlayFlashUpdate(GameHudUpdateEvent ev)
    {
        if (IsVisible)
        {
            if (PlayFlashWhile?.Invoke(this) ?? false)
            {
                playFlashTimer -= ev.DeltaTime;
                if(playFlashTimer < 0f)
                {
                    playFlashTimer = 0.9f;
                    PlayFlashOnce();
                }
            }
            else
            {
                playFlashTimer = 0f;
            }
        }
        else
        {
            playFlashTimer = 0f;
        }
    }

    public void UpdateVisibility()
    {
        try
        {
            //表示・非表示切替
            bool isVisible = IsVisible;
            VanillaButton.gameObject.SetActive(isVisible);
            if (isVisible) {
                if (IsBroken) TryGenerateBrokenAlternative();
                if(brokenAlternative.AsBoolFast()) brokenAlternative!.gameObject.SetActive(IsBroken);
                VanillaButton.graphic.enabled = !IsBroken;
            }

            //使用可能性切替
            if (IsAvailableUnsafe)
                VanillaButton.SetEnabled();
            else
            {
                VanillaButton.SetDisabled();
                if (IsBroken) VanillaButton.buttonLabelText.color = Palette.EnabledColor;
            }


        }
        catch(Exception exception)
        {
            NebulaLogger.Instance.Error("[At " + VanillaButton.buttonLabelText.text + "] " + exception.ToString());
        }
    }

    void OnHudActiveChange(Patches.HudActivePatch.HudActiveChangeEvent ev) => UpdateVisibility();

    ValueObserver<bool> cooldownTextColorObserver;
    ValueObserver<string> cooldownTextObserver;
    void OnHudUpdate(GameHudUpdateEvent ev)
    {
        UpdateVisibility();

        OnUpdate?.Invoke(this);

        if (EffectActive && (EffectTimer == null || !EffectTimer.IsProgressing)) InactivateEffect();

        VanillaButton.SetCooldownFill(CurrentTimer?.Percentage ?? 0f);

        string timerText = "";
        if (CurrentTimer?.IsProgressing ?? false) timerText = CurrentTimer.TimerText ?? "";
        var cooldownText = VanillaButton.cooldownTimerText;
        cooldownTextObserver.Set(timerText);
        cooldownTextColorObserver.Set(EffectActive);

        if ((keyCode?.KeyDownInGame ?? false) || (canUseByMouseClick && CheckMouseClick() && !AmongUsUtil.UsingMouseMovement)) DoClick();
        if (subKeyCode?.KeyDownInGame ?? false) DoSubClick();
    }

    void OnMeetingStart(MeetingStartEvent ev)
    {
        OnMeeting?.Invoke(this);
    }


    public ModAbilityButtonImpl InactivateEffect()
    {
        if (!EffectActive) return this;
        EffectActive = false;
        OnEffectEnd?.Invoke(this);
        return this;
    }

    public ModAbilityButtonImpl ToggleEffect()
    {
        if (EffectActive)
            InactivateEffect();
        else
            ActivateEffect();

        return this;
    }

    public ModAbilityButtonImpl ActivateEffect()
    {
        if (EffectActive) return this;
        EffectActive = true;
        EffectTimer?.Start();
        OnEffectStart?.Invoke(this);
        return this;
    }

    public ModAbilityButtonImpl StartCoolDown()
    {
        CoolDownTimer?.Start();
        return this;
    }

    public bool UseCoolDownSupport { get; set; } = true;

    void OnGameReenabled(TaskPhaseRestartEvent ev) {
        if (UseCoolDownSupport) StartCoolDown();
        OnStartTaskPhase?.Invoke(this);
    }

    public void OnGameStart(GameStartEvent ev) {
        if (UseCoolDownSupport && CoolDownTimer != null && CoolDownTimer is TimerImpl timer)
        {
            if (GeneralConfigurations.UseShortenCooldownAtGameStartOption)
                timer.Start(Mathn.Min(timer.Max, CoolDownOnGameStart));
            else
                StartCoolDown();
        }
        OnStartTaskPhase?.Invoke(this);
    }

    public ModAbilityButton DoClick()
    {
        //効果中でなく、クールダウン中ならばなにもしない
        if (!EffectActive && (CoolDownTimer?.IsProgressing ?? false)) return this;
        //使用可能でないかを判定 (ボタン発火のタイミングと可視性更新のタイミングにずれが生じうるためここで再計算)
        if (!IsAvailable) return this;
        if (IsBroken) return this;

        //簒奪が判明したらボタンを壊して、なにも起こさない
        if(RelatedAbility?.IsUsurped ?? false)
        {
            IsBroken = true;
            OnBroken?.Invoke(this);
            return this;
        }

        OnClick?.Invoke(this);
        return this;
    }

    public ModAbilityButton DoSubClick()
    {
        //見えないボタンは使用させない
        if (!(Visibility?.Invoke(this) ?? true)) return this;
        if (IsBroken) return this;

        //簒奪が判明したらボタンを壊して、なにも起こさない
        if (RelatedAbility?.IsUsurped ?? false)
        {
            IsBroken = true;
            OnBroken?.Invoke(this);
            return this;
        }

        OnSubAction?.Invoke(this);
        return this;
    }

    ModAbilityButton ModAbilityButton.Break()
    {
        if (!IsBroken)
        {
            IsBroken = true;
            OnBroken?.Invoke(this);
        }
        return this;
    }

    public ModAbilityButtonImpl SetSprite(Sprite? sprite)
    {
        VanillaButton.graphic.sprite = sprite;
        if (sprite != null) VanillaButton.graphic.SetCooldownNormalizedUvs();
        return this;
    }

    public ModAbilityButtonImpl SetLabel(string translationKey) => SetRawLabel(Language.Translate("button.label." + translationKey));

    public ModAbilityButtonImpl SetRawLabel(string rawText)
    {
        VanillaButton.buttonLabelText.text = rawText;
        return this;
    }

    public ModAbilityButtonImpl SetLabelType(ModAbilityButton.LabelType labelType)
    {
        Material? material = null;
        switch (labelType)
        {
            case ModAbilityButton.LabelType.Standard:
                material = AmongUsLLImpl.HudManagerBridge.UseButtonVanillaSettings[ImageNames.UseButton].FontMaterial;
                break;
            case ModAbilityButton.LabelType.Utility:
                material = AmongUsLLImpl.HudManagerBridge.UseButtonVanillaSettings[ImageNames.PolusAdminButton].FontMaterial;
                break;
            case ModAbilityButton.LabelType.Impostor:
                material = RoleManager.Instance.GetRole(RoleTypes.Shapeshifter).Ability.FontMaterial;
                break;
            case ModAbilityButton.LabelType.Crewmate:
                material = RoleManager.Instance.GetRole(RoleTypes.Engineer).Ability.FontMaterial;
