            spriteLoader = DividedSpriteLoader.FromResource("Nebula.Resources.KeyBindCharacters0.png", 100f, 18, 19, true);
            _ = new KeyCodeInfo(KeyCode.Tab, "Tab", spriteLoader, 0);
