            _ = new KeyCodeInfo(KeyCode.RightControl, "RControl", spriteLoader, 2);
            _ = new KeyCodeInfo(KeyCode.LeftControl, "LControl", spriteLoader, 3);
            _ = new KeyCodeInfo(KeyCode.RightAlt, "RAlt", spriteLoader, 4);
