                    if (MeetingHud.Instance.AsBoolFast()) return;

                    if (!(GameOperatorManager.Instance?.Run(new PlayerInteractPlayerLocalEvent(MyPlayer, target, new(RealPlayerOnly: true))).IsCanceled ?? false))
                    {
                        var icon = iconHolder.AddPlayer(target.RealPlayer);
                        var lifespan = new FlexibleLifespan(this);
                        var timer = NebulaAPI.Modules.Timer(lifespan, TrackerDurationOption);
                        var arrow = new TrackingArrowAbility(target.RealPlayer, 0f, VColor.White).Register(lifespan);
                        timer.SetCondition(() => !MeetingHud.Instance.AsBoolFast() && !ExileController.Instance.AsBoolFast());
                        timer.Start();

                        trackings.Add(new(target.RealPlayer, icon, timer, lifespan));
                        StatsTrack.Progress();
                        new StaticAchievementToken("niceTracker.common1");
                        trackedHistoryMask.Add(target.RealPlayer);

                        trackButton.StartCoolDown();
                    }
                };
                trackButton.SetAsUsurpableButton(this);

                (trackButton.EffectTimer as GameTimer)?.SetCondition(() => !MeetingHud.Instance.AsBoolFast() && !ExileController.Instance.AsBoolFast());

                float meetingCooldown = 0f;
                GameOperatorManager.Instance?.Subscribe<GameUpdateEvent>(ev => {
                    //meetingCooldownの更新
                    if (MeetingHud.Instance.AsBoolFast() || ExileController.Instance.AsBoolFast()) meetingCooldown = 5f;
                    else meetingCooldown -= ev.DeltaTime;

                    //trackingsの更新
                    trackings.RemoveAll(tuple =>
                    {
                        //座標の更新
                        var lastPos = tuple.LastPosition;
                        var currentPos = tuple.Player.Position;
                        tuple.LastPosition = currentPos;

                        if(meetingCooldown < 0f)
                        {
                            if (lastPos.HasValue && lastPos.Value.Distance(currentPos) > 5f) new StaticAchievementToken("niceTracker.common2");
                        }

                        if (!tuple.Duration.IsProgressing || tuple.Player.IsDead)
                        {
                            tuple.Lifespan.Release();
                            iconHolder.Remove(tuple.Icon);
                            return true;
                        }
                        tuple.Icon.SetText(tuple.Duration.TimerText ?? "");
                        return false;
                    });
                }, this);
                if (ResetOnMeetingOption)
                {
                    GameOperatorManager.Instance?.Subscribe<MeetingStartEvent>(ev =>
                    {
                        foreach (var tuple in trackings)
                        {
                            tuple.Lifespan.Release();
                            iconHolder.Remove(tuple.Icon);
                        }
                        trackings.Clear();
                    }, this);
                }

                int monitorKillCount = 0;
                GameOperatorManager.Instance?.Subscribe<PlayerKillPlayerEvent>(ev =>
                {
                    if (trackings.Any(tuple => tuple.Player == ev.Murderer))
                    {
                        monitorKillCount++;
                        if(monitorKillCount == AmongUsUtil.AdjustedImpostors(GamePlayer.AllPlayers.Count()))
                        {
                            GameOperatorManager.Instance?.Subscribe<GameEndEvent>(ev => {
                                if (
                                    ev.EndState.EndCondition == NebulaGameEnd.CrewmateWin &&
                                    GamePlayer.AllPlayers.All(p =>
