                                        (!p.IsTrueCrewmate || p.PlayerState != PlayerStates.Exiled) //クルーメイトを追放していない
                                    )) new StaticAchievementToken("niceTracker.challenge");

                            }, this);
                        }
                    }

                }, this);

            }
        }
    }
